class Solution {
    fun maximumXorProduct(a:Long,b:Long,n:Int):Int{
        var first=(a shr n) shl n;
        var second=(b shr n) shl n;
        for(index in n-1 downTo 0){
            val bit=1L shl index;
            if((a shr index and 1L)==(b shr index and 1L)){
                first=first or bit;
                second=second or bit
            }else if(first<second)first=first or bit else second=second or bit
        };
        val mod=1_000_000_007L;
        return (first%mod*(second%mod)%mod).toInt()
    }
}

